output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper is obliged to check out the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_depot": "at(1,5)",
        "cart_waiting_at_depot": "cartAt(1,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "check_out_entry_cart": {
          "pre": {
            "and": [
              "cart_depot",
              "cart_waiting_at_depot",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "check_out_entry_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Items should not be carried by hand; item pickup is permitted only while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "item_pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_before_exit",
    "text": "Before leaving the store, the shopper is obliged to park the cart in the return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "A shopper is forbidden to leave the cart anywhere other than the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "Exiting is forbidden while still pushing the cart or while the cart is not parked at the return bay.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_parked_at_return_bay"
        }
      },
      "events": {
        "improper_exit": {
          "pre": {
            "and": [
              "EXIT",
              {
                "or": [
                  "pushing_cart",
                  "cart_not_returned"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit"
    }
  },
  {
    "id": "drop_cart_immediately_at_bay",
    "text": "Once a shopper reaches the return bay while pushing the cart, any action other than leaving the cart there is forbidden.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "pushing_cart_at_return_bay": {
          "and": [
            "return_bay",
            "pushing_cart"
          ]
        }
      },
      "events": {
        "leave_cart_at_return_bay": {
          "pre": {
            "and": [
              "pushing_cart_at_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart_at_return_bay",
          {
            "not": "LEAVE_CART"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_east_in_front_corridor",
    "text": "The shopper may walk east through the front corridor after returning the cart, but is forbidden to push the cart east there.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "front_corridor": {
          "or": [
            "at(0,1)",
            "at(1,1)",
            "at(2,1)",
            "at(3,1)",
            "at(4,1)",
            "at(5,1)",
            "at(6,1)",
            "at(7,1)",
            "at(8,1)"
          ]
        },
        "pushing_cart_in_front_corridor": {
          "and": [
            "pushing_cart",
            "front_corridor"
          ]
        }
      },
      "events": {
        "push_cart_east_in_front_corridor": {
          "pre": {
            "and": [
              "pushing_cart_in_front_corridor",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_in_front_corridor"
    }
  },
  {
    "id": "no_interaction_after_cart_return",
    "text": "After the cart has been parked in the return bay, the shopper should proceed to the exit without further interactions.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "post_return_phase": "cart_parked_at_return_bay"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "post_return_phase",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
